//
//  Sprites.swift
//  Flying Toasters
//
//  The genuine After Dark sprite GIFs, embedded as base64 so the saver and the
//  headless tools are fully self-contained. 256x64 toaster sheet (4 wing frames)
//  + 64x64 toast. Extracted from the original "\After Dark: Flying Toasters.saver"
//  (Bryan Braun / after-dark-css pixel art).
//

import Foundation

enum Sprites {
    static let toasterSheetGIFBase64 = ""
    static let toastGIFBase64 = ""

    static var toasterSheetData: Data { Data(base64Encoded: toasterSheetGIFBase64)! }
    static var toastData: Data { Data(base64Encoded: toastGIFBase64)! }
}
